#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> minSubarraySort(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> ans;
        ans.reserve(n - k + 1);

        for (int i = 0; i <= n - k; ++i) {
            int left = -1, right = -1;
            int mx = nums[i];

            for (int j = i; j < i + k; ++j) {
                if (nums[j] < mx) {
                    right = j;
                } else {
                    mx = nums[j];
                }
            }

            if (right == -1) {
                ans.push_back(0);
                continue;
            }

            int mi = nums[i + k - 1];
            for (int j = i + k - 1; j >= i; --j) {
                if (nums[j] > mi) {
                    left = j;
                } else {
                    mi = nums[j];
                }
            }

            ans.push_back(right - left + 1);
        }

        return ans;
    }
};

